/// <summary>
/// MPJ_24808_PalletRounding
/// Pallet rounding logic for a sales line.
/// </summary>

class METPalletRounding
{
}

Method.Source:
    /// <summary>
    /// Performs pallet rounding.
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_custAccount">Customer account</param>
    /// <param name = "_siteId">Inventory site id</param>
    /// <param name = "_orderedQty">Ordered quantity</param>    
    /// <returns>New ordered quantity</returns>
    public InventQty applyPalletRounding(ItemId         _itemId, 
                                         CustAccount    _custAccount, 
                                         InventSiteId   _siteId, 
                                         InventQty      _orderedQty)
    {
        METInventItemOrderSetup         metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_itemId, _siteId);

        InventQty                       orderedQty  = _orderedQty;
        METPalletRoundingPercentage     roundingPercentage;

        if (metInventItemOrderSetup.RecId)
        {
            roundingPercentage  = this.findPalletRoundingPercentage(_itemId, _custAccount, _siteId);

            if (roundingPercentage > 0)
            {
                InventQty   modQty = _orderedQty mod metInventItemOrderSetup.PalletQty;

                if (((modQty * 100)/metInventItemOrderSetup.PalletQty) > roundingPercentage)
                {
                    orderedQty  += metInventItemOrderSetup.PalletQty - modQty;
                }
            }
        }

        return orderedQty;
    }

/// <summary> /// Finds pallet rounding percentage. /// </summary> /// <param name = "_itemId">ItemId</param> /// <param name = "_custAccount">Customer account</param> /// <param name = "_siteId">Inventory site id</param> /// <returns>Pallet rounding percentage</returns> public METPalletRoundingPercentage findPalletRoundingPercentage(ItemId _itemId, CustAccount _custAccount, InventSiteId _siteId) { EcoResCategoryName category = this.findItemCategory(_itemId); METCustOperGroupId custOperGroupId = CustTable::find(_custAccount).METCustOperGroupId;
METPalletRoundingPolicyHeader policyHeader; METPalletRoundingPolicyLine policyLine; METPalletRoundingPercentage roundingPercentage;
select firstonly RecId from policyLine where policyLine.RuleType == METPalletRoundingPolicyRuleType::Exclude && policyLine.InventSiteId == _siteId && policyLine.ItemCode == TableGroupAll::Table && policyLine.ItemRelation == _itemId && ((policyLine.AccountCode == TableGroupAll::Table && policyLine.AccountRelation == _custAccount) || (policyLine.AccountCode == TableGroupAll::GroupId && policyLine.AccountRelation == custOperGroupId) || policyLine.AccountCode == TableGroupAll::All) exists join policyHeader where policyHeader.PolicyName == policyLine.PolicyName && policyHeader.Active == NoYes::Yes;
if (!policyLine.RecId) { select firstonly RecId from policyLine where policyLine.RuleType == METPalletRoundingPolicyRuleType::Include && policyLine.InventSiteId == _siteId && ((policyLine.AccountCode == TableGroupAll::Table && policyLine.AccountRelation == _custAccount && policyLine.ItemCode == TableGroupAll::Table && policyLine.ItemRelation == _itemId) || (policyLine.AccountCode == TableGroupAll::Table && policyLine.AccountRelation == _custAccount && policyLine.ItemCode == TableGroupAll::GroupId && policyLine.ItemRelation == category) || (policyLine.AccountCode == TableGroupAll::Table && policyLine.AccountRelation == _custAccount && policyLine.ItemCode == TableGroupAll::All) || (policyLine.AccountCode == TableGroupAll::GroupId && policyLine.AccountRelation == custOperGroupId && policyLine.ItemCode == TableGroupAll::Table && policyLine.ItemRelation == _itemId) || (policyLine.AccountCode == TableGroupAll::GroupId && policyLine.AccountRelation == custOperGroupId && policyLine.ItemCode == TableGroupAll::GroupId && policyLine.ItemRelation == category) || (policyLine.AccountCode == TableGroupAll::GroupId && policyLine.AccountRelation == custOperGroupId && policyLine.ItemCode == TableGroupAll::All) || (policyLine.AccountCode == TableGroupAll::All && policyLine.ItemCode == TableGroupAll::Table && policyLine.ItemRelation == _itemId) || (policyLine.AccountCode == TableGroupAll::All && policyLine.ItemCode == TableGroupAll::GroupId && policyLine.ItemRelation == category) || (policyLine.AccountCode == TableGroupAll::All && policyLine.ItemCode == TableGroupAll::All)) join RoundingPercentage, RecId from policyHeader where policyHeader.PolicyName == policyLine.PolicyName && policyHeader.Active == NoYes::Yes;
if (policyHeader.RecId) { roundingPercentage = policyHeader.RoundingPercentage; }
}
return roundingPercentage; }

    /// <summary>
    /// Finds item category.
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>Item category</returns>
    public EcoResCategoryName findItemCategory(ItemId   _itemId)
    {
        InventTable             inventTable = InventTable::find(_itemId);
        EcoResCategory          category;               

        category    = EcoResProductCategory::findCategoryByProduct(inventTable.Product, 
                                                                   EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::Retail).CategoryHierarchy);

        while (category.RecId && category.Level > METConstants::CategoryLevel)
        {
            category    = EcoResCategory::find(category.ParentCategory);
        }

        return ((category.RecId && category.Level == METConstants::CategoryLevel) ? category.Name : '');
    }
